using System;using System.Text;using System.Collections;using System.Collections.Generic;
public static class BuyerSourcePresentation{
 static string S(Dictionary<string,object>d,string k){object v;return d.TryGetValue(k,out v)&&v!=null?Convert.ToString(v):"unknown";}
 public static string Describe(Dictionary<string,object>report){var b=new StringBuilder("Requested original: "+S(report,"source_url")+"\r\nSource identity: "+S(report,"source_identity_status")+"\r\n");if(S(report,"source_identity_status")=="integrity_failure_no_refetch")b.AppendLine("INTEGRITY FAILURE: cached receipt is not verified; old cache preserved; no network retry.");if(report.ContainsKey("quarantine_reason"))b.AppendLine("QUARANTINED: "+S(report,"quarantine_reason")).AppendLine("Received payload is not attributed original question text or buyer evidence.");object raw;if(report.TryGetValue("received_payloads",out raw)&&raw is IEnumerable&&!(raw is string)&&!(raw is IDictionary))foreach(var item in(IEnumerable)raw){var r=item as Dictionary<string,object>;if(r==null)continue;b.AppendLine("Received request: "+S(r,"request_url")).AppendLine("Preserved payload: "+S(r,"payload_file")+" | SHA256: "+S(r,"payload_sha256")+" | bytes: "+S(r,"bytes"));}return b.ToString();}
}
